import numpy as np
from typing import Tuple, Optional

_NUMPY_DTYPES_MAPPING = {
    np.int8: 0, np.int16: 1, np.int32: 2, np.int64: 3,
    np.uint8: 4, np.uint16: 5, np.uint32: 6, np.uint64: 7,
    np.float16: 8, np.float32: 9, np.float64: 10,
    np.complex64: 11, np.complex128: 12,
    np.bool_: 13, np.object_: 14
}

class NoHeaderNumpySerializer:
    def __init__(self):
        self._dtype_to_indices = {v: k for k, v in _NUMPY_DTYPES_MAPPING.items()}

    def serialize(self, item: np.ndarray) -> Tuple[bytes, Optional[str]]:
        bytes_object = item.tobytes()
        dtype_index = self._dtype_to_indices.get(item.dtype)
        if dtype_index is not None:
            return bytes_object, f"no_header_numpy:{dtype_index}"
        else:
            return bytes_object, None
```

